 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    marker = next(c for c in colors if c not in (0, 1))
    pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == marker]
    r0 = min(r for r, c in pts)
    c0 = min(c for r, c in pts)
    shape = [(r-r0, c-c0) for r, c in pts]
    sh, sw = max(r for r, c in shape)+1, max(c for r, c in shape)+1
    out = [row[:] for row in grid]
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if all(grid[r+dr][c+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r+dr][c+dc] = marker
    return out
